package openai

import (
	"bytes"
	"encoding/json"
)

// reasoningDetailsAcc accumulates streamed delta.reasoning_details entries
// into the ordered array the provider expects back verbatim on replay.
//
// OpenRouter's contract: "the entire sequence of consecutive reasoning blocks
// must match the outputs generated by the model during the original request;
// you cannot rearrange or modify the sequence". Entries carry provider-opaque
// fields (id, format, signature, encrypted data) that must survive untouched,
// so entries are kept as raw JSON objects and only the incremental payload
// fields are merged.
//
// Observed streaming shape (gpt-5.6 via OpenRouter): a reasoning.summary
// entry streams its "summary" string one fragment per chunk (same type,
// format, and index throughout), then a reasoning.encrypted entry arrives
// whole with an "id". A change in type, index, or id starts a new entry.
type reasoningDetailsAcc struct {
	entries []map[string]json.RawMessage
}

// reasoningDetailIncrementalFields are the payload fields that stream as
// string fragments and are concatenated across chunks of the same entry.
// Every other field (id, format, signature, ...) is overwritten by the
// latest non-empty value.
var reasoningDetailIncrementalFields = []string{"text", "summary", "data"}

// add merges one delta.reasoning_details array (raw JSON) into the
// accumulator. Malformed input is dropped silently: reasoning details are a
// quality optimization, never worth failing the stream over.
func (a *reasoningDetailsAcc) add(raw json.RawMessage) {
	var incoming []map[string]json.RawMessage
	if err := json.Unmarshal(raw, &incoming); err != nil {
		return
	}
	for _, entry := range incoming {
		if len(entry) == 0 {
			continue
		}
		last := a.lastEntry()
		if last != nil && sameReasoningEntry(last, entry) {
			mergeReasoningEntry(last, entry)
			continue
		}
		// Copy so later mutation of the decode buffer can't alias.
		fresh := make(map[string]json.RawMessage, len(entry))
		for k, v := range entry {
			fresh[k] = v
		}
		a.entries = append(a.entries, fresh)
	}
}

func (a *reasoningDetailsAcc) lastEntry() map[string]json.RawMessage {
	if len(a.entries) == 0 {
		return nil
	}
	return a.entries[len(a.entries)-1]
}

// marshal returns the accumulated array as raw JSON, or nil when empty.
func (a *reasoningDetailsAcc) marshal() json.RawMessage {
	if len(a.entries) == 0 {
		return nil
	}
	out, err := json.Marshal(a.entries)
	if err != nil {
		return nil
	}
	return out
}

// sameReasoningEntry reports whether an incoming fragment continues the
// current entry: identical type, index, and format, and no conflicting id.
func sameReasoningEntry(current, incoming map[string]json.RawMessage) bool {
	for _, key := range []string{"type", "index", "format"} {
		if !bytes.Equal(normalizedRawField(current, key), normalizedRawField(incoming, key)) {
			return false
		}
	}
	curID := normalizedRawField(current, "id")
	incID := normalizedRawField(incoming, "id")
	if len(curID) > 0 && len(incID) > 0 && !bytes.Equal(curID, incID) {
		return false
	}
	return true
}

// mergeReasoningEntry folds an incoming fragment into the current entry:
// incremental string fields concatenate, everything else takes the latest
// non-null value.
func mergeReasoningEntry(current, incoming map[string]json.RawMessage) {
	for key, val := range incoming {
		if isRawNull(val) {
			continue
		}
		if isIncrementalReasoningField(key) {
			var curStr, incStr string
			curOK := json.Unmarshal(normalizedRawField(current, key), &curStr) == nil
			if json.Unmarshal(val, &incStr) == nil && curOK {
				merged, err := json.Marshal(curStr + incStr)
				if err == nil {
					current[key] = merged
					continue
				}
			}
		}
		current[key] = val
	}
}

func isIncrementalReasoningField(key string) bool {
	for _, f := range reasoningDetailIncrementalFields {
		if key == f {
			return true
		}
	}
	return false
}

// normalizedRawField returns the raw value for key, treating a missing key
// and JSON null the same (nil).
func normalizedRawField(m map[string]json.RawMessage, key string) json.RawMessage {
	v, ok := m[key]
	if !ok || isRawNull(v) {
		return nil
	}
	return v
}

func isRawNull(v json.RawMessage) bool {
	return len(v) == 0 || bytes.Equal(bytes.TrimSpace(v), []byte("null"))
}
